use shapes::{Circle, Rectangle, Triangle, Shape, total_area, total_perimeter};
use std::f64::consts::PI;

#[test]
fn test_circle() {
    let c = Circle { radius: 1.0 };
    assert!((c.area() - PI).abs() < 1e-9);
    assert!((c.perimeter() - 2.0 * PI).abs() < 1e-9);
}

#[test]
fn test_rectangle() {
    let r = Rectangle { width: 3.0, height: 4.0 };
    assert_eq!(r.area(), 12.0);
    assert_eq!(r.perimeter(), 14.0);
}

#[test]
fn test_triangle() {
    // 3-4-5 right triangle
    let t = Triangle { a: 3.0, b: 4.0, c: 5.0 };
    assert_eq!(t.area(), 6.0); // Heron's formula
    assert_eq!(t.perimeter(), 12.0);
}

#[test]
fn test_total_area() {
    let shapes: Vec<Box<dyn Shape>> = vec![
        Box::new(Rectangle { width: 2.0, height: 3.0 }),
        Box::new(Rectangle { width: 4.0, height: 5.0 }),
    ];
    assert_eq!(total_area(&shapes), 26.0);
}

#[test]
fn test_total_perimeter() {
    let shapes: Vec<Box<dyn Shape>> = vec![
        Box::new(Rectangle { width: 1.0, height: 1.0 }),
        Box::new(Rectangle { width: 2.0, height: 3.0 }),
    ];
    assert_eq!(total_perimeter(&shapes), 14.0); // 4+10
}

